    ldr   r0, =DUMP
    .irp k, 0, 4, 8, 12, 16, 20, 24, 28, 32, 36, 40, 44, 48
    ldr   r2, [r0, #\k]
    PRINT_HEX r2
    .endr
    .if \flags
    ldr   r2, [r0, #52]
    PRINT_HEX r2
    .endif
    .if \slot
    ldr   r0, =\slot
    .irp k, 0, 4, 8, 12
    ldr   r2, [r0, #\k]
    PRINT_HEX r2
    .endr
    .endif
    PUTC  '\n'
    ldr   r7, =USART3_BASE
    POOL
.endm

